const { Buffer } = require("node:buffer");

function filledBuffer(value) {
  return Buffer.alloc(4096, value);
}

function unchanged(buffer, value) {
  return buffer.every((byte) => byte === value);
}

function makeParserProbe() {
  const counters = {
    bodyBytes: 0,
    execute: 0,
    headersComplete: 0,
    messageComplete: 0,
  };
  let resolveCompleted;
  const completed = new Promise((resolve) => {
    resolveCompleted = resolve;
  });
  return {
    callbacks: {
      body(chunk) {
        counters.bodyBytes += chunk?.byteLength ?? 0;
      },
      execute() {
        counters.execute++;
      },
      headersComplete() {
        counters.headersComplete++;
        return 0;
      },
      messageBegin() {},
      messageComplete() {
        counters.messageComplete++;
        resolveCompleted();
      },
      headers() {},
    },
    completed,
    snapshot() {
      return { ...counters };
    },
  };
}

function probeHttp2Consume(socket) {
  const http2 = require("node:http2");
  const { Duplex } = require("node:stream");
  const dummySocket = new Duplex({
    read() {},
    write(_chunk, _encoding, callback) {
      callback();
    },
  });
  const session = http2.connect("http://localhost", {
    createConnection: () => dummySocket,
  });
  const handleSymbol = Object.getOwnPropertySymbols(session).find(
    (symbol) => symbol.description === "kHandle",
  );
  const handle = session[handleSymbol];
  const protectedHandle = socket._handle;
  const result = handle.consumeStream(protectedHandle);
  const unchanged = socket._handle === protectedHandle &&
    typeof protectedHandle.protectedInspectorPeer() === "string";
  session.destroy();
  dummySocket.destroy();
  return { result, unchanged };
}

