function connectWithFalseyHttpToken(port) {
  const net = require("node:net");
  const socket = new net.Socket();
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      socket.destroy();
      resolve(value);
    };
    socket.once("connect", () => finish("ALLOWED"));
    socket.once("error", (error) => {
      const denied = error?.code === "EACCES" ||
        String(error?.message).includes("inspector activation");
      finish(denied ? "DENIED" : "BROKEN");
    });
    socket.connect({
      __odenHttpNetToken: undefined,
      host: "127.0.0.1",
      port,
    });
  });
}

